  return <div className="space-y-6"><PageHeading eyebrow="Submission review" title="Node fundamentals & the module system" description="Priya Sharma · Node · Week 8 · Submitted 7 days ago" action={<Status tone="amber">Awaiting review</Status>} /><div className="grid gap-4 xl:grid-cols-[1.1fr_.9fr]"><div className="space-y-4"><Surface className="p-5"><h2 className="font-semibold text-slate-900">Task brief</h2><p className="mt-3 text-sm leading-6 text-slate-600">Build a command-line tool that reads, transforms, and writes files using Node’s module system.</p><div className="mt-4 rounded-xl bg-slate-50 p-4"><p className="text-xs font-semibold uppercase tracking-wide text-slate-500">Done when</p><ul className="mt-3 space-y-2 text-sm text-slate-600"><li className="flex gap-2"><Check className="mt-0.5 h-4 w-4 text-emerald-600" />The project runs from a clean clone</li><li className="flex gap-2"><Check className="mt-0.5 h-4 w-4 text-emerald-600" />The README explains setup and decisions</li><li className="flex gap-2"><CircleDot className="mt-0.5 h-4 w-4 text-amber-600" />A mentor reviews and signs off</li></ul></div></Surface><Surface className="p-5"><div className="flex items-center gap-3"><Avatar person="priya" size={42} /><div><p className="text-sm font-semibold text-slate-900">Priya Sharma</p><p className="text-xs text-slate-500">Submitted evidence</p></div></div><p className="mt-4 text-sm leading-6 text-slate-600">I built a CLI that reads a CSV, normalizes participant records, and writes validated JSON. The README covers the module boundary and error cases.</p><div className="mt-4 flex items-center justify-between rounded-xl border border-slate-200 bg-slate-50 p-3"><span><strong className="block text-sm">node-data-cli</strong><span className="text-xs text-slate-500">Repository link · fictional preview</span></span><Status>Attached</Status></div></Surface></div><Surface className="p-5"><h2 className="font-semibold text-slate-900">Your review</h2><label className="mt-5 block text-xs font-semibold text-slate-600">Quality rating<span className="mt-2 flex gap-1">{[1,2,3,4,5].map((star) => <button type="button" key={star} aria-label={`${star} stars`} onClick={() => setRating(star)} className="rounded-md p-1 text-amber-500"><Star className="h-5 w-5" fill={star <= rating ? "currentColor" : "none"} /></button>)}</span></label><label className="mt-5 block text-xs font-semibold text-slate-600">Feedback<textarea value={feedback} onChange={(event) => setFeedback(event.target.value)} className="mt-2 min-h-36 w-full rounded-xl border border-slate-200 p-3 text-sm font-normal leading-6 outline-none focus:border-[#43aa9a] focus:ring-2 focus:ring-[#c9ebe4]" /></label><div className="mt-4 flex items-center justify-between rounded-xl bg-slate-50 p-3 text-xs"><span>Recognition on approval</span><strong>15 XP + 15 coins</strong></div>{result ? <div role="status" className="mt-4 rounded-xl bg-emerald-50 p-4 text-sm leading-6 text-emerald-800"><strong>Simulation complete.</strong> In a live workspace, this would move to “{result === "approved" ? "Approved" : "Changes requested"}” and notify Priya. Nothing was saved here.</div> : <div className="mt-4 grid gap-2 sm:grid-cols-2"><button type="button" onClick={() => complete("changes")} className="rounded-xl border border-slate-200 px-4 py-3 text-sm font-semibold text-slate-700">Request changes</button><button type="button" onClick={() => complete("approved")} className="rounded-xl bg-[#008b7d] px-4 py-3 text-sm font-semibold text-white">Approve submission</button></div>}</Surface></div></div>;
